/* The denominator: every flag the two Makefiles test, and the
 * number of them a binary can report at all. */
#define FUZZ_CONFIG_FLAGS 272
#define FUZZ_CONFIG_WITNESSED 193

/* All three masks are over the same two bits: 1 hostapd, 2 the
 * supplicant.
 *
 * daemons: which Makefile tests the flag at all.
 * witness: which binary can REPORT it. A bit set in daemons and
 *          clear here is the silent case -- the flag steers that
 *          daemon's link and reaches no -D, so absent from
 *          fuzz_config_on[] does not mean off for it.
 * stock:   which upstream defconfig SETS it: the baseline a
 *          finding's strength is measured against, because behind
 *          a flag upstream ships off is a weaker claim than in a
 *          default build.
 * value:   the Makefile tests this one for its VALUE, not for being
 *          set, so on/off is the wrong question about it. */
struct fuzz_config_roster_entry {
	const char *name;
	unsigned char daemons;
	unsigned char witness;
	unsigned char stock;
	unsigned char value;
};

